import type { Metadata } from 'next';
import { site } from '@/content/site';
import { imageUrl } from './images';

type PageMetaInput = {
  title: string;
  description: string;
  path: string;
  image?: string;
  type?: 'website' | 'article';
  noIndex?: boolean;
};

export const absoluteUrl = (path = '/') => `${site.url}${path.startsWith('/') ? path : `/${path}`}`;

/** Default social sharing image (generated by `npm run images`). */
export const defaultOgImage = '/images/hero-living-panelling-1600.jpg';

export function pageMetadata({ title, description, path, image, type = 'website', noIndex }: PageMetaInput): Metadata {
  const url = absoluteUrl(path);
  const ogImage = image ? imageUrl(image) : defaultOgImage;
  return {
    title,
    description,
    alternates: { canonical: url },
    openGraph: {
      type,
      url,
      title: `${title} | ${site.name}`,
      description,
      siteName: site.name,
      locale: site.locale,
      images: [{ url: absoluteUrl(ogImage), width: 1600, height: 900, alt: `${site.name} — ${site.tagline}` }],
    },
    twitter: {
      card: 'summary_large_image',
      title: `${title} | ${site.name}`,
      description,
      images: [absoluteUrl(ogImage)],
    },
    robots: noIndex ? { index: false, follow: true } : undefined,
  };
}
